import sys

# Read A and B from standard input
# The input format is "A B"
try:
    line = sys.stdin.read()
    if line:
        parts = line.split()
        if len(parts) >= 2:
            A = int(parts[0])
            B = int(parts[1])
            print((A + B) ** 2)
except Exception:
    pass

